ext('c12_bio_ch10',[C("🐛","जैव सुरक्षा और जोखिम",["नए जीन से एलर्जी का डर","जंगली रिश्तेदारों में जीन फैलना","कड़ी जाँच ज़रूरी","भारत में जीईएसी समिति"],"आनुवंशिक रूप से बदली फसलों के बारे में कुछ चिंताएँ भी हैं। एक चिंता यह है कि नया जीन एलर्जी पैदा कर सकता है। दूसरी चिंता यह है कि वह जंगली रिश्तेदार पौधों में फैल सकता है। इसलिए ऐसी फसलों की कड़ी जाँच होती है। भारत में यह काम जीईएसी नाम की समिति देखती है।")],6)
ext('c12_bio_ch11',[C("🐦","जीवन-इतिहास की विविधता",["कुछ जीव एक बार बहुत संतान देते","कुछ जीव कई बार कम संतान","सालमन मछली का उदाहरण","बांस का एक बार फूलना"],"हर जीव का जीवन-इतिहास अलग होता है। प्रशांत सालमन मछली जीवन में एक बार ही ढेर सारे अंडे देती है। कई पक्षी और स्तनधारी हर साल कम संतान पैदा करते हैं। बांस भी कई साल में एक बार फूलता है। यह अंतर जीव के वातावरण और रहन-सहन के अनुसार विकसित हुआ है।")],6)
ext('c12_bio_ch12',[C("📊","पारिस्थितिक पिरामिडों की सीमाएँ",["खाद्य जाल नहीं दिखाते","एक जीव कई स्तरों में","अपघटक को स्थान नहीं","फिर भी ऊर्जा समझाने में उपयोगी"],"पारिस्थितिक पिरामिड की कुछ सीमाएँ हैं। वह केवल सीधी खाद्य शृंखला दिखाता है, खाद्य जाल नहीं। एक ही जीव कई पोषण स्तरों में आ सकता है, जो पिरामिड में नहीं दिखता। अपघटकों को भी इसमें जगह नहीं मिलती। फिर भी ऊर्जा का प्रवाह समझने के लिए यह बहुत काम का है।"),C("🌊","तालाब का पारितंत्र",["उत्पादक: शैवाल और जलीय पौधे","उपभोक्ता: मछलियाँ और कीट","अपघटक: तल के जीवाणु","सूर्य ऊर्जा का स्रोत"],"तालाब एक छोटा पूरा पारितंत्र है। उसमें शैवाल और जलीय पौधे उत्पादक हैं। छोटे कीट और मछलियाँ उपभोक्ता हैं। तल पर मौजूद जीवाणु और कवक अपघटन करते हैं। पूरे तंत्र को ऊर्जा सूर्य से मिलती है।")],6)
ext('c12_bio_ch13',[C("🐅","भारत की संरक्षण योजनाएँ",["प्रोजेक्ट टाइगर","जैवमंडल आरक्षित क्षेत्र","वन्यजीव संरक्षण अधिनियम","रामसर स्थल"],"भारत में जैव विविधता बचाने के लिए कई योजनाएँ चल रही हैं। बाघों को बचाने के लिए प्रोजेक्ट टाइगर शुरू किया गया। जैवमंडल आरक्षित क्षेत्र बनाए गए हैं और वन्यजीव संरक्षण कानून लागू है। महत्त्वपूर्ण आर्द्रभूमियों को रामसर स्थल का दर्जा दिया जाता है।")],6)
